-- ==========================================
-- PERSONAL HUB — ARREGLO RÁPIDO SUPABASE
-- Pega TODO esto en el SQL Editor y ejecútalo (una vez).
--
-- Qué arregla:
--   1) Permisos de service_role (arregla el 403 "permission denied
--      for table ..." que rompe la API de Vercel, /api/users, /api/push
--      y cualquier script con la service key).
--   2) Permiso de escritura en content para usuarios autenticados
--      (la política RLS INSERT WITH CHECK is_admin() lo controla;
--      sin este GRANT el INSERT daba "permission denied").
--   3) Backfill de perfiles: crea la fila en profiles de cualquier
--      cuenta creada antes del trigger (sin ella is_admin() = false y
--      TODAS las escrituras fallan con "violates row-level security").
--      Y marca admin a admin@personalhub.com (idempotente).
--   4) Carga el catálogo de series (tu lista: Dragon Ball, Gravity
--      Falls, Crepúsculo, Minions, Mi Villano Favorito, Moana, Cars,
--      El Señor de los Anillos, Obsesión, Cocina, KiberSport, Sherlock,
--      etc.).
-- ==========================================

-- ==========================================
-- 1) PERMISOS service_role (API de Vercel + scripts)
-- ==========================================
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT USAGE, SELECT ON ALL SEQUENCES IN SCHEMA public TO service_role;
GRANT EXECUTE ON ALL FUNCTIONS IN SCHEMA public TO service_role;

-- ==========================================
-- 2) ESCRITURA en content (controlada por la política is_admin)
-- ==========================================
GRANT SELECT, INSERT, UPDATE, DELETE ON content TO authenticated;

-- ==========================================
-- 3) PERFILES: backfill + rol admin (idempotente)
-- ==========================================
ALTER TABLE public.profiles DISABLE TRIGGER profiles_prevent_role_change;

INSERT INTO public.profiles (id, email, name, avatar_url, role, created_at, updated_at)
SELECT
  au.id,
  COALESCE(au.email, ''),
  COALESCE(au.raw_user_meta_data->>'name', split_part(COALESCE(au.email, ''), '@', 1), 'Usuario'),
  COALESCE(au.raw_user_meta_data->>'avatar_url', ''),
  CASE WHEN LOWER(au.email) = 'admin@personalhub.com' THEN 'admin' ELSE 'user' END,
  au.created_at,
  au.created_at
FROM auth.users au
LEFT JOIN public.profiles p ON p.id = au.id
WHERE p.id IS NULL;

UPDATE public.profiles SET role = 'admin' WHERE LOWER(email) = 'admin@personalhub.com';
ALTER TABLE public.profiles ENABLE TRIGGER profiles_prevent_role_change;

-- ==========================================
-- 4) DIAGNÓSTICO (si algo sigue fallando, pégame este resultado)
-- ==========================================
SELECT email, role, enabled FROM public.profiles ORDER BY created_at;

